import{c as r,ah as l,L as e,O as t}from"./chunks/framework.YKVbmyBD.js";const p=JSON.parse('{"title":"Linux 常用快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/shortcut-key.md","filePath":"fovlin-notes/linux-guide/shortcut-key.md"}'),h={name:"fovlin-notes/linux-guide/shortcut-key.md"};function i(n,a,c,d,s,o){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="linux-常用快捷键" tabindex="-1">Linux 常用快捷键 <a class="header-anchor" href="#linux-常用快捷键" aria-label="Permalink to “Linux 常用快捷键”">​</a></h1><h3 id="常用快捷键" tabindex="-1">常用快捷键 <a class="header-anchor" href="#常用快捷键" aria-label="Permalink to “常用快捷键”">​</a></h3><h2 id="常用快捷键-1" tabindex="-1">常用快捷键 <a class="header-anchor" href="#常用快捷键-1" aria-label="Permalink to “常用快捷键”">​</a></h2><p>以下是一些在命令行中较为常用的快捷键。</p><h4 id="tab-键" tabindex="-1">Tab 键 <a class="header-anchor" href="#tab-键" aria-label="Permalink to “Tab 键”">​</a></h4><p>命令、文件名等补全。</p><h4 id="ctrl-c" tabindex="-1">Ctrl + c <a class="header-anchor" href="#ctrl-c" aria-label="Permalink to “Ctrl + c”">​</a></h4><p>取消当前行输入的命令，相当于 Ctrl + Break。</p><h4 id="ctrl-z" tabindex="-1">Ctrl + z <a class="header-anchor" href="#ctrl-z" aria-label="Permalink to “Ctrl + z”">​</a></h4><p>后端运行。</p><h4 id="ctrl-l" tabindex="-1">Ctrl + l <a class="header-anchor" href="#ctrl-l" aria-label="Permalink to “Ctrl + l”">​</a></h4><p>清屏，相当于执行 clear 命令。</p><h4 id="ctrl-s" tabindex="-1">Ctrl + s <a class="header-anchor" href="#ctrl-s" aria-label="Permalink to “Ctrl + s”">​</a></h4><p>暂停当前终端。</p><h4 id="ctrl-q" tabindex="-1">Ctrl + q <a class="header-anchor" href="#ctrl-q" aria-label="Permalink to “Ctrl + q”">​</a></h4><p>恢复当前终端。</p><h4 id="ctrl-a" tabindex="-1">Ctrl + a <a class="header-anchor" href="#ctrl-a" aria-label="Permalink to “Ctrl + a”">​</a></h4><p>光标移动到行首（Beginning of line），等同 Home 键。</p><h4 id="ctrl-e" tabindex="-1">Ctrl + e <a class="header-anchor" href="#ctrl-e" aria-label="Permalink to “Ctrl + e”">​</a></h4><p>光标移动到行尾（End of line），等同 End 键。</p><h4 id="alt-f" tabindex="-1">Alt + f <a class="header-anchor" href="#alt-f" aria-label="Permalink to “Alt + f”">​</a></h4><p>光标向前（Forward）移动到下一个单词。</p><h4 id="alt-b" tabindex="-1">Alt + b <a class="header-anchor" href="#alt-b" aria-label="Permalink to “Alt + b”">​</a></h4><p>光标往回（Backward）移动到前一个单词。</p><h4 id="ctrl-u" tabindex="-1">Ctrl + u <a class="header-anchor" href="#ctrl-u" aria-label="Permalink to “Ctrl + u”">​</a></h4><p>删除光标所在位置左边与行首之间的所有字符。</p><h4 id="ctrl-k" tabindex="-1">Ctrl + k <a class="header-anchor" href="#ctrl-k" aria-label="Permalink to “Ctrl + k”">​</a></h4><p>删除光标所在位置与行尾之间的所有字符。</p><h4 id="ctrl-w" tabindex="-1">Ctrl + w <a class="header-anchor" href="#ctrl-w" aria-label="Permalink to “Ctrl + w”">​</a></h4><p>删除光标所在位置前任意个空格及其前的一个单词，或光标所在位置左边至所在单词首的所有字符。</p><h4 id="alt-d" tabindex="-1">Alt + d <a class="header-anchor" href="#alt-d" aria-label="Permalink to “Alt + d”">​</a></h4><p>删除光标所在位置后任意个空格及其后的一个单词，或光标所在位置至所在单词尾的所有字符。</p><h4 id="ctrl-y" tabindex="-1">Ctrl + y <a class="header-anchor" href="#ctrl-y" aria-label="Permalink to “Ctrl + y”">​</a></h4><p>复制你上一次删除或剪切的条目。</p><h4 id="alt-u" tabindex="-1">Alt + u <a class="header-anchor" href="#alt-u" aria-label="Permalink to “Alt + u”">​</a></h4><p>转换光标所在位置后的一个单词为大写，或光标所在单词位置至此单词尾的字母为大写。</p><h4 id="alt-l" tabindex="-1">Alt + l <a class="header-anchor" href="#alt-l" aria-label="Permalink to “Alt + l”">​</a></h4><p>转换光标所在位置后的一个单词为小写，或光标所在单词位置至此单词尾的字母为小写。</p><h4 id="alt" tabindex="-1">Alt + . <a class="header-anchor" href="#alt" aria-label="Permalink to “Alt + .”">​</a></h4><p>在光标处输入最近历史命令的最后一个字符串，如果此命令只有单个字符串，则输入此字符串。可持续使用以持续切换为更前的命令。</p><h4 id="ctrl-r" tabindex="-1">Ctrl + r <a class="header-anchor" href="#ctrl-r" aria-label="Permalink to “Ctrl + r”">​</a></h4><p>依据用户在：提示符后的输入字符串匹配查找 history 记录中命令条目。</p><h4 id="ctrl-g" tabindex="-1">Ctrl + g <a class="header-anchor" href="#ctrl-g" aria-label="Permalink to “Ctrl + g”">​</a></h4><p>从历史搜索模式（Ctrl + r）退出。</p><h4 id="num" tabindex="-1">!num <a class="header-anchor" href="#num" aria-label="Permalink to “!num”">​</a></h4><p>执行 history 记录中第 num 条命令条目，num 正整数时，为正序；负数时，为反序。</p><h4 id="string-p" tabindex="-1">!string:p <a class="header-anchor" href="#string-p" aria-label="Permalink to “!string:p”">​</a></h4><p>输出最近的以 string 开头的命令条目。等同 !?string?。</p><h4 id="bang-命令" tabindex="-1">Bang(!)命令 <a class="header-anchor" href="#bang-命令" aria-label="Permalink to “Bang(!)命令”">​</a></h4><h4 id="" tabindex="-1">!! <a class="header-anchor" href="#" aria-label="Permalink to “!!”">​</a></h4><p>输出并执行最近已执行过的一条命令。</p><h4 id="num-1" tabindex="-1">!num <a class="header-anchor" href="#num-1" aria-label="Permalink to “!num”">​</a></h4><p>执行 history 记录中第 num 条命令条目，num 正整数时，为正序；负数时，为反序。</p><h4 id="num-p" tabindex="-1">!num:p <a class="header-anchor" href="#num-p" aria-label="Permalink to “!num:p”">​</a></h4><p>输出第 num 条命令条目，不执行。</p><h4 id="num-gs-str1-str2" tabindex="-1">!num:gs/str1/str2/ <a class="header-anchor" href="#num-gs-str1-str2" aria-label="Permalink to “!num:gs/str1/str2/”">​</a></h4><p>将第 num 条命令条目中的 str1 字符串替换为str2，（若不加 g，则仅替换第一个匹配）。</p><h4 id="string" tabindex="-1">!string <a class="header-anchor" href="#string" aria-label="Permalink to “!string”">​</a></h4><p>输出最近已执行过的以 string 开头的命令条目。等同 !?string?。</p><h4 id="string-1" tabindex="-1">!?string? <a class="header-anchor" href="#string-1" aria-label="Permalink to “!?string?”">​</a></h4><p>输出最近已执行过的以 string 开头的命令条目。等同 !string。</p><h4 id="string-p-1" tabindex="-1">!string:p <a class="header-anchor" href="#string-p-1" aria-label="Permalink to “!string:p”">​</a></h4><p>输出最近已执行过的以 string 开头的命令条目。</p><h4 id="abc" tabindex="-1">^abc <a class="header-anchor" href="#abc" aria-label="Permalink to “^abc”">​</a></h4><p>删除最近已执行过的命令中的 abc 字符串，并执行。</p><h4 id="foo-bar" tabindex="-1">^foo^bar <a class="header-anchor" href="#foo-bar" aria-label="Permalink to “^foo^bar”">​</a></h4><p>将最近已执行过的命令中的 foo 字符串替换为 bar，并执行。</p><h4 id="-1" tabindex="-1">!$ <a class="header-anchor" href="#-1" aria-label="Permalink to “!$”">​</a></h4><p>执行最近已执行过的命令中的最后一个参数。</p><h4 id="-2" tabindex="-1">!* <a class="header-anchor" href="#-2" aria-label="Permalink to “!*”">​</a></h4><p>执行最近已执行过的命令中的所有参数。</p><h4 id="p" tabindex="-1">!*:p <a class="header-anchor" href="#p" aria-label="Permalink to “!*:p”">​</a></h4><p>输出最近已执行过的命令中的所有参数。</p><h2 id="移动光标" tabindex="-1">移动光标 <a class="header-anchor" href="#移动光标" aria-label="Permalink to “移动光标”">​</a></h2><h4 id="ctrl-a-1" tabindex="-1">Ctrl + a <a class="header-anchor" href="#ctrl-a-1" aria-label="Permalink to “Ctrl + a”">​</a></h4><p>光标移动到行首（Ahead of line），即 Home 键。</p><h4 id="ctrl-e-1" tabindex="-1">Ctrl + e <a class="header-anchor" href="#ctrl-e-1" aria-label="Permalink to “Ctrl + e”">​</a></h4><p>光标移动到行尾（End of line），即 End 键。</p><h4 id="ctrl-xx" tabindex="-1">Ctrl + xx <a class="header-anchor" href="#ctrl-xx" aria-label="Permalink to “Ctrl + xx”">​</a></h4><p>光标在输入的命令行首与行尾切换跳转。</p><h4 id="ctrl-f" tabindex="-1">Ctrl + f <a class="header-anchor" href="#ctrl-f" aria-label="Permalink to “Ctrl + f”">​</a></h4><p>光标向前（Forward）/右移动一个字符位置。</p><h4 id="ctrl-b" tabindex="-1">Ctrl + b <a class="header-anchor" href="#ctrl-b" aria-label="Permalink to “Ctrl + b”">​</a></h4><p>光标往回（Backward）/左移动一个字符位置。</p><h4 id="alt-f-1" tabindex="-1">Alt + f <a class="header-anchor" href="#alt-f-1" aria-label="Permalink to “Alt + f”">​</a></h4><p>光标向前（Forward）移动到下一个单词。</p><h4 id="alt-b-1" tabindex="-1">Alt + b <a class="header-anchor" href="#alt-b-1" aria-label="Permalink to “Alt + b”">​</a></h4><p>光标往回（Backward）移动到前一个单词。</p><h2 id="编辑命令" tabindex="-1">编辑命令 <a class="header-anchor" href="#编辑命令" aria-label="Permalink to “编辑命令”">​</a></h2><h4 id="tab-键-1" tabindex="-1">Tab 键 <a class="header-anchor" href="#tab-键-1" aria-label="Permalink to “Tab 键”">​</a></h4><p>命令、文件名等补全。</p><h4 id="ctrl-d" tabindex="-1">Ctrl + d <a class="header-anchor" href="#ctrl-d" aria-label="Permalink to “Ctrl + d”">​</a></h4><p>删除一个字符，即 Delete 键(命令行若无字符，相当于exit，处理多行标准输入时也表示 EOF)。</p><h4 id="ctrl-h" tabindex="-1">Ctrl + h <a class="header-anchor" href="#ctrl-h" aria-label="Permalink to “Ctrl + h”">​</a></h4><p>退格删除一个字符，即 Backspace 键。</p><h4 id="ctrl-u-1" tabindex="-1">Ctrl + u <a class="header-anchor" href="#ctrl-u-1" aria-label="Permalink to “Ctrl + u”">​</a></h4><p>删除光标所在位置左边与行首之间的所有字符。</p><h4 id="ctrl-k-1" tabindex="-1">Ctrl + k <a class="header-anchor" href="#ctrl-k-1" aria-label="Permalink to “Ctrl + k”">​</a></h4><p>删除光标所在位置与行尾之间的所有字符。</p><h4 id="ctrl-w-1" tabindex="-1">Ctrl + w <a class="header-anchor" href="#ctrl-w-1" aria-label="Permalink to “Ctrl + w”">​</a></h4><p>删除光标所在位置前任意个空格及其前的一个单词，或光标所在位置左边至所在单词首的所有字符。</p><h4 id="alt-d-1" tabindex="-1">Alt + d <a class="header-anchor" href="#alt-d-1" aria-label="Permalink to “Alt + d”">​</a></h4><p>删除光标所在位置后任意个空格及其后的一个单词，或光标所在位置至所在单词尾的所有字符。</p><h4 id="ctrl-y-1" tabindex="-1">Ctrl + y <a class="header-anchor" href="#ctrl-y-1" aria-label="Permalink to “Ctrl + y”">​</a></h4><p>复制你上一次删除或剪切的条目。</p><h4 id="ctrl-t" tabindex="-1">Ctrl + t <a class="header-anchor" href="#ctrl-t" aria-label="Permalink to “Ctrl + t”">​</a></h4><p>光标处在行尾，则交换前两个字符的位置；否则交换光标处字符与前一字符位置，并且光标向右移动单个字符位置。</p><h4 id="alt-t" tabindex="-1">Alt + t <a class="header-anchor" href="#alt-t" aria-label="Permalink to “Alt + t”">​</a></h4><p>依据光标所在位置，交换其所处单词和前一个单词的位置；交换其前后两个单词的位置；交换其前最后两个单词的位置（注意空格位置的变化）。</p><h4 id="alt-u-1" tabindex="-1">Alt + u <a class="header-anchor" href="#alt-u-1" aria-label="Permalink to “Alt + u”">​</a></h4><p>转换光标所在位置后的一个单词为大写，或光标所在单词位置至此单词尾的字母为大写。</p><h4 id="alt-l-1" tabindex="-1">Alt + l <a class="header-anchor" href="#alt-l-1" aria-label="Permalink to “Alt + l”">​</a></h4><p>转换光标所在位置后的一个单词为小写，或光标所在单词位置至此单词尾的字母为小写。</p><h4 id="alt-1" tabindex="-1">Alt + . <a class="header-anchor" href="#alt-1" aria-label="Permalink to “Alt + .”">​</a></h4><p>在光标处输入最近历史命令的最后一个字符串，如果此命令只有单个字符串，则输入此字符串。可持续使用以持续切换为更前的命令。</p><h4 id="ctrl" tabindex="-1">Ctrl + - <a class="header-anchor" href="#ctrl" aria-label="Permalink to “Ctrl + -”">​</a></h4><p>依次撤销命令行除添加字符的首次修改及其后的所有修改，否则恢复到空行。等同 Ctrl + x + u。</p><h4 id="ctrl-x-u" tabindex="-1">Ctrl + x + u <a class="header-anchor" href="#ctrl-x-u" aria-label="Permalink to “Ctrl + x + u”">​</a></h4><p>按住 Ctrl 的同时再先后按 x 和 u，依次撤销命令行除添加字符的首次修改及其后的所有修改，否则恢复到空行。等同 Ctrl + -。</p><h2 id="查找历史命令" tabindex="-1">查找历史命令 <a class="header-anchor" href="#查找历史命令" aria-label="Permalink to “查找历史命令”">​</a></h2><h4 id="ctrl-p" tabindex="-1">Ctrl + p <a class="header-anchor" href="#ctrl-p" aria-label="Permalink to “Ctrl + p”">​</a></h4><p>调出命令历史中的前一条（Previous）命令，即向上箭头键↑。</p><h4 id="ctrl-n" tabindex="-1">Ctrl + n <a class="header-anchor" href="#ctrl-n" aria-label="Permalink to “Ctrl + n”">​</a></h4><p>调出命令历史中的下一条（Next）命令，即向下箭头键↓。</p><h4 id="ctrl-r-1" tabindex="-1">Ctrl + r <a class="header-anchor" href="#ctrl-r-1" aria-label="Permalink to “Ctrl + r”">​</a></h4><p>依据用户在：提示符后的输入匹配查找 history 记录中命令条目。</p><h4 id="ctrl-g-1" tabindex="-1">Ctrl + g <a class="header-anchor" href="#ctrl-g-1" aria-label="Permalink to “Ctrl + g”">​</a></h4><p>从历史搜索模式（Ctrl + r）退出。</p><h2 id="控制命令" tabindex="-1">控制命令 <a class="header-anchor" href="#控制命令" aria-label="Permalink to “控制命令”">​</a></h2><h4 id="ctrl-c-1" tabindex="-1">Ctrl + c <a class="header-anchor" href="#ctrl-c-1" aria-label="Permalink to “Ctrl + c”">​</a></h4><p>取消当前行输入的命令，相当于Ctrl + Break。</p><h4 id="ctrl-s-1" tabindex="-1">Ctrl + s <a class="header-anchor" href="#ctrl-s-1" aria-label="Permalink to “Ctrl + s”">​</a></h4><p>暂停当前终端。</p><h4 id="ctrl-q-1" tabindex="-1">Ctrl + q <a class="header-anchor" href="#ctrl-q-1" aria-label="Permalink to “Ctrl + q”">​</a></h4><p>恢复当前终端。</p><h4 id="ctrl-z-1" tabindex="-1">Ctrl + z <a class="header-anchor" href="#ctrl-z-1" aria-label="Permalink to “Ctrl + z”">​</a></h4><p>后端运行。</p><h4 id="ctrl-l-1" tabindex="-1">Ctrl + l <a class="header-anchor" href="#ctrl-l-1" aria-label="Permalink to “Ctrl + l”">​</a></h4><p>清空屏幕并重新显示当前命令行内容。</p><h4 id="ctrl-alt-delete" tabindex="-1">[Ctrl] + [Alt] + [Delete] <a class="header-anchor" href="#ctrl-alt-delete" aria-label="Permalink to “[Ctrl] + [Alt] + [Delete]”">​</a></h4><p>关机并重新引导系统。在正常关机步骤不起作用时，可使用此方式。</p><h4 id="ctrl-alt-fn-alt-fn" tabindex="-1">[Ctrl] + [Alt] + [Fn] / [Alt] + [Fn] <a class="header-anchor" href="#ctrl-alt-fn-alt-fn" aria-label="Permalink to “[Ctrl] + [Alt] + [Fn] / [Alt] + [Fn]”">​</a></h4><p>切换虚拟终端。默认， [F1]至[F6] 是命令行终端， [F7] 是 X 终端。</p><h4 id="alt-tab" tabindex="-1">[Alt] + [Tab] <a class="header-anchor" href="#alt-tab" aria-label="Permalink to “[Alt] + [Tab]”">​</a></h4><p>在图形化桌面环境中切换任务。</p><h4 id="ctrl-alt-backspace" tabindex="-1">[Ctrl] + [Alt] + [Backspace] <a class="header-anchor" href="#ctrl-alt-backspace" aria-label="Permalink to “[Ctrl] + [Alt] + [Backspace]”">​</a></h4><p>杀死当前的 X 会话，返回到登录会话。如果正常退出步骤不起作用，你可以使用这种方法。</p><h2 id="其它快捷键" tabindex="-1">其它快捷键 <a class="header-anchor" href="#其它快捷键" aria-label="Permalink to “其它快捷键”">​</a></h2><h4 id="esc-键" tabindex="-1">Esc 键 <a class="header-anchor" href="#esc-键" aria-label="Permalink to “Esc 键”">​</a></h4><p>连续按 3 次显示所有的支持的终端命令。</p><h4 id="esc-b" tabindex="-1">Esc + b <a class="header-anchor" href="#esc-b" aria-label="Permalink to “Esc + b”">​</a></h4><p>移动到当前单词的开头</p><h4 id="esc-f" tabindex="-1">Esc + f <a class="header-anchor" href="#esc-f" aria-label="Permalink to “Esc + f”">​</a></h4><p>移动到当前单词的结尾</p><h4 id="esc-t" tabindex="-1">Esc + t <a class="header-anchor" href="#esc-t" aria-label="Permalink to “Esc + t”">​</a></h4><p>颠倒光标所在处及其相邻单词的位置</p><h4 id="esc-d" tabindex="-1">Esc + d <a class="header-anchor" href="#esc-d" aria-label="Permalink to “Esc + d”">​</a></h4><p>由光标位置开始，删除单词，直到单词结束，往右侧（还有剪切功能）</p><h4 id="esc-c" tabindex="-1">Esc + c <a class="header-anchor" href="#esc-c" aria-label="Permalink to “Esc + c”">​</a></h4><p>使下一个单词首字母大写, 同时光标前进一个单词, 如光标停留在单词的某个字母上, 如 word 中的 o 字母上, 则 o 字母变大写. 而不是 w</p><h4 id="esc-u" tabindex="-1">Esc + u <a class="header-anchor" href="#esc-u" aria-label="Permalink to “Esc + u”">​</a></h4><p>使下一个单词所有字母变大写, 同时光标前进一个单词, 同上, 如光标在 o 字母上, 则 ord 变大写, w 不变.</p><h4 id="esc" tabindex="-1">Esc+. <a class="header-anchor" href="#esc" aria-label="Permalink to “Esc+.”">​</a></h4><p>上一个命令的后面的参数</p><h4 id="esc-操作次数-操作动作" tabindex="-1">Esc + 操作次数 操作动作 <a class="header-anchor" href="#esc-操作次数-操作动作" aria-label="Permalink to “Esc + 操作次数 操作动作”">​</a></h4><p>指定操作次数，重复执行指定的操作。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to “参考”">​</a></h2><p><a href="https://zhuanlan.zhihu.com/p/338681998" target="_blank" rel="noreferrer">知乎专栏</a></p>',168)])])}const f=r(h,[["render",i]]);export{p as __pageData,f as default};
